 function view(route){if(route==='habits')return habitsView();if(route==='notes')return notesView();if(route==='projects')return projectsView();if(route==='sport')return sportView();if(route==='canvas')return canvasView();if(route==='progress')return progressView();if(route==='profile')return intro('profile')+`<article class="alpha-card"><h2>${tr('localProfile')}</h2><p>${tr('localProfileNote')}</p></article>`;if(route==='sync')return intro('sync')+`<article class="alpha-card"><h2>${tr(getError()?'localError':'localSaved')}</h2><p class="muted">${tr('revision')}: ${getState().revision}</p><p>${tr('localSyncNote')}</p>${getError()?`<p class="error">${esc(getError())}</p>`:''}<button type="button" class="action-button action-button--secondary" data-route="settings">${tr('settings')}</button></article>`;return null;}
 function paintCamera(){const world=document.querySelector('.canvas-world');if(!world||!camera)return;world.style.transform=`translate(${camera.x}px,${camera.y}px) scale(${camera.zoom})`;$('canvas-zoom').textContent=Math.round(camera.zoom*100)+'%';}
 function fitBoard(){const b=list(getState(),'canvases').find(b=>b.id===selectedBoard),v=document.querySelector('.canvas-viewport');if(!v||!b)return;const x=Math.min(0,...b.nodes.map(n=>n.x)),y=Math.min(0,...b.nodes.map(n=>n.y)),right=Math.max(100,...b.nodes.map(n=>n.x+n.width)),bottom=Math.max(100,...b.nodes.map(n=>n.y+n.height)),zoom=Math.min(1,(v.clientWidth-32)/(right-x),(v.clientHeight-32)/(bottom-y));camera={board:b.id,x:16-x*zoom,y:16-y*zoom,zoom};paintCamera();}
 function zoomBy(factor){const v=document.querySelector('.canvas-viewport');if(!v||!camera)return;const old=camera.zoom,next=Math.max(.15,Math.min(3,old*factor)),cx=v.clientWidth/2,cy=v.clientHeight/2;camera.x=cx-(cx-camera.x)*next/old;camera.y=cy-(cy-camera.y)*next/old;camera.zoom=next;paintCamera();}
